        bool reverted;
        bool returnedOk;

        try c.transfer(from, caddr, tos, v) returns (bool ok) {
            returnedOk = ok;
            reverted = false;
        } catch {
            returnedOk = false;
            reverted = true;
        }

        if (tos.length == 0) {
            assert(reverted);
        } else {

            uint successCount;
            uint total = tos.length;
            for (uint i = 0; i < total; i++) {
                (bool s,) = caddr.call(abi.encodeWithSelector(bytes4(keccak256("transferFrom(address,address,uint256)")), from, tos[i], v));
                if (s) successCount++;
            }

            if (reverted) {
                assert(successCount < total);
            } else {
                assert(returnedOk && successCount == total);
            }
        }
    }

    receive() external payable {}
}

